import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    # Count recent opponent cooperations (last 10 rounds or all if less)
    window_size = min(10, n)
    recent_history = history[-window_size:]
    opp_coops = sum(1 for _, o in recent_history if o == 'C')
    coop_rate = opp_coops / window_size

    # Detect persistent mutual defection trap
    if n >= 4:
        last4 = history[-4:]
        if all(a == 'D' and b == 'D' for a, b in last4):
            return 'C'

    # Strategy logic based on opponent's last move and overall trend
    if opp_last == 'D':
        # Opponent defected. 
        # If they are generally cooperative, forgive with some probability to break noise/accidental defections
        # But retaliate primarily.
        if my_last == 'C':
            # We were nice, they were mean. Retaliate.
            # However, if they are highly cooperative overall, maybe it was noise?
            if coop_rate > 0.8:
                if rng.random() < 0.2:
                    return 'C' # Forgive accidental/noisy D
            return 'D'

        # We both defected last round. Try to escape the DD cycle if possible.
        # If the opponent is mostly cooperative, take a chance on cooperation.
        if coop_rate > 0.5:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            # Against defectors, stick to D unless very long streak suggests change
            if rng.random() < 0.1:
                return 'C'
            return 'D'

    else:
        # Opponent cooperated.
        if my_last == 'D':
            # We exploited them, but they still cooperate. 
            # Continue exploiting if they seem passive, or reciprocate C to maintain relationship?
            # Tit-for-tat says return C. Exploitative says stay D.
            # Let's return C to build trust/rank, unless they are ALWAYS cooperating (unconditional cooperator).
            if n >= 10:
                recent_opp_c = sum(1 for _, o in history[-10:] if o == 'C')
                if recent_opp_c == 10:
                    return 'D' # Exploit unconditional cooperator
            return 'C'

        # Both cooperated. Stay cooperative.
        return 'C'
